{
  "configModule": "type Mapping = Record<string, any>;\nfunction mapping(value: unknown, name: string): Mapping {\n  if (value === undefined || value === null) return {};\n  if (typeof value !== \"object\" || Array.isArray(value)) throw new Error(`${name} must be a YAML mapping`);\n  return value as Mapping;\n}\nfunction parse(text: string, name: string): Mapping {\n  try { return mapping(Bun.YAML.parse(text), name); }\n  catch { throw new Error(`Invalid ${name} YAML; no files changed`); }\n}\nfunction serialize(value: Mapping, original: string): string {\n  // Leave healthy configs byte-for-byte unchanged, including comments.\n  if (JSON.stringify(value) === JSON.stringify(parse(original, \"config\"))) return original;\n  const text = Bun.YAML.stringify(value) + \"\\n\";\n  return original.includes(\"\\r\\n\") ? text.replaceAll(\"\\n\", \"\\r\\n\") : text;\n}\nconst sol = \"chatgpt-web/gpt-5.6-sol\";\nconst instant = \"chatgpt-web/gpt-5.6-sol-instant\";\nexport function configureOmpWeb(configText: string, modelsText: string, baseUrl: string, judgeUrl?: string) {\n  const config = parse(configText, \"OMP config\");\n  const models = parse(modelsText, \"OMP models\");\n  const roles = mapping(config.modelRoles, \"modelRoles\");\n  Object.assign(roles, {\n    default: `codex-chatgpt-web/${sol}:high`,\n    vision: `codex-chatgpt-web/${sol}:high`,\n    plan: `codex-chatgpt-web/${sol}:high`,\n    task: `codex-chatgpt-web/${sol}:high`,\n    commit: `codex-chatgpt-web/${instant}:auto`,\n    web: `openai-codex/${sol}:high`,\n  });\n  config.modelRoles = roles;\n  const providers = mapping(models.providers, \"providers\");\n  const definitions = [\n    { id: sol, name: \"GPT-5.6 Sol (Web)\", preferWebsockets: false, reasoning: true,\n      thinking: { mode: \"effort\", efforts: [\"medium\", \"high\", \"xhigh\"], defaultLevel: \"high\" },\n      input: [\"text\"], supportsTools: true, contextWindow: 90000, maxTokens: 16384 },\n    { id: instant, name: \"GPT-5.6 Sol Instant (Web)\", preferWebsockets: false, reasoning: true,\n      thinking: { mode: \"effort\", efforts: [\"low\"], defaultLevel: \"low\" },\n      input: [\"text\"], supportsTools: true, contextWindow: 41000, maxTokens: 16384 },\n  ];\n  for (const name of [\"codex-chatgpt-web\", \"openai-codex\"]) {\n    const previous = mapping(providers[name], name);\n    if (previous.models !== undefined && !Array.isArray(previous.models)) throw new Error(`${name}.models must be a list`);\n    const entries = previous.models ?? [];\n    const headers = mapping(previous.headers, `${name}.headers`);\n    const provider = { ...previous, baseUrl, api: \"openai-codex-responses\", auth: \"none\",\n      // This header marks OMP requests; the extension supplies each session's actual cwd.\n      headers: { ...headers, \"x-omp-cwd\": \"OMP_WORKSPACE_CWD\" },\n      models: [...entries.filter((model: any) => !definitions.some(d => d.id === model?.id)), ...definitions],\n    } as Mapping;\n    delete provider.apiKey;\n    delete provider.oauth;\n    delete provider.authHeader;\n    for (const key of Object.keys(provider.headers)) {\n      if (key.toLowerCase() === \"authorization\") delete provider.headers[key];\n    }\n    providers[name] = provider;\n  }\n  // Existing judge settings are retained unless the user supplies a router URL.\n  if (judgeUrl) {\n    const previous = mapping(providers[\"9router\"], \"9router\");\n    const entries = previous.models ?? [];\n    if (!Array.isArray(entries)) throw new Error(\"9router.models must be a list\");\n    const provider = { ...previous, baseUrl: judgeUrl, api: \"typesafe\",\n      models: [...entries.filter((m: any) => m?.id !== \"oc/jev-1.13-free\"),\n        { id: \"oc/jev-1.13-free\", name: \"JEV 1.13 Free (9Router)\", reasoning: false, input: [\"text\"], supportsTools: false }],\n    } as Mapping;\n    if (!previous.apiKey && previous.auth !== \"none\") provider.apiKey = \"NINE_ROUTER_API_KEY\";\n    providers[\"9router\"] = provider;\n    roles.judge = \"9router/oc/jev-1.13-free\";\n  }\n  models.providers = providers;\n  return { config: serialize(config, configText), models: serialize(models, modelsText) };\n}\n\nif (import.meta.main) {\n  try {\n    const [configPath, modelsPath, baseUrl, judgeUrl] = Bun.argv.slice(2);\n    if (!configPath || !modelsPath || !baseUrl) throw new Error(\"Config paths and shim URL required\");\n    const read = async (path: string) => await Bun.file(path).exists() ? await Bun.file(path).text() : \"\";\n    const originalConfig = await read(configPath), originalModels = await read(modelsPath);\n    const updated = configureOmpWeb(originalConfig, originalModels, baseUrl, judgeUrl);\n    console.log(JSON.stringify({ changes: [\n      ...(updated.config !== originalConfig ? [{ path: configPath, text: updated.config }] : []),\n      ...(updated.models !== originalModels ? [{ path: modelsPath, text: updated.models }] : []),\n    ] }));\n  } catch (error) {\n    // Never print config content or credentials in diagnostics.\n    console.error(error instanceof Error ? error.message : \"Cannot prepare OMP Web configuration\");\n    process.exitCode = 1;\n  }\n}\n",
  "extension": "import type { ExtensionAPI } from \"@oh-my-pi/pi-coding-agent\";\n\n// Command-backed model headers cache `!pwd` across subagents. Use the actual\n// session cwd at request time so each isolated worker gets its own workspace.\nexport default function codexChatGptWebWorkspace(pi: ExtensionAPI) {\n  // A title inference would open another ChatGPT tab alongside the worker.\n  // Child sessions already have useful agent IDs; retain any existing name.\n  pi.on(\"session_start\", async (_event, ctx) => {\n    if ([\"codex-chatgpt-web\", \"openai-codex\"].includes(ctx.model?.provider ?? \"\") && ctx.agent.kind === \"sub\" && !pi.getSessionName()) {\n      await pi.setSessionName(ctx.agent.id);\n    }\n  });\n  pi.on(\"before_provider_request\", (event, ctx) => {\n    if (![\"codex-chatgpt-web\", \"openai-codex\"].includes(ctx.model?.provider ?? \"\")) return;\n    if (!event.payload || typeof event.payload !== \"object\" || Array.isArray(event.payload)) return;\n    return { ...event.payload, __omp_cwd: ctx.cwd };\n  });\n}\n",
  "files": {
    "server.ts": "import { isAbsolute, join } from \"node:path\";\nimport { homedir } from \"node:os\";\nimport { guardResponseStream } from \"./sse-watchdog\";\nimport { record, addCodexEnvironment } from \"./compatibility\";\nimport { taskLabelResponse } from \"./task-label\";\nimport { translateToolCallIds, translateResponseStream } from \"./tool-call-ids\";\n\nconst listenHost = \"127.0.0.1\";\nconst listenPort = Number(process.env.OMP_CODEX_WEB_SHIM_PORT || 17842);\nconst upstreamOrigin = process.env.OMP_CODEX_WEB_UPSTREAM || \"http://127.0.0.1:17841\";\nconst cwdHeader = \"x-omp-cwd\";\n\n\nasync function interruptNativeTurn(threadId: string | undefined, turnId: string | undefined) {\n  if (!threadId || !turnId) return;\n  const configPath = join(process.env.CODEX_CHATGPT_WEB_HOME || join(homedir(), \".codex-chatgpt-web\"), \"config.json\");\n  const config = await Bun.file(configPath).json();\n  if (typeof config.controlToken !== \"string\") throw new Error(\"Missing local Web control token\");\n  const result = await fetch(new URL(\"/admin/interrupt-turn\", upstreamOrigin), {\n    method: \"POST\",\n    headers: { authorization: `Bearer ${config.controlToken}`, \"content-type\": \"application/json\" },\n    body: JSON.stringify({ threadId, turnId }),\n    signal: AbortSignal.timeout(5000),\n  });\n  if (!result.ok) throw new Error(`Native turn interruption HTTP ${result.status}`);\n  console.log(\"OMP interrupted native Web turn\", { thread: threadId.slice(0, 8), turn: turnId.slice(0, 8), ...await result.json() });\n}\n\nconst threadTails = new Map<string, Promise<void>>();\n\nasync function acquireThread(threadId: string) {\n  const previous = threadTails.get(threadId) ?? Promise.resolve();\n  const queued = threadTails.has(threadId);\n  let releaseCurrent!: () => void;\n  const current = new Promise<void>(resolve => { releaseCurrent = resolve; });\n  const tail = previous.catch(() => {}).then(() => current);\n  threadTails.set(threadId, tail);\n\n  if (queued) console.log(\"OMP queue wait\", { thread: threadId.slice(0, 8) });\n  await previous.catch(() => {});\n  if (queued) console.log(\"OMP queue start\", { thread: threadId.slice(0, 8) });\n\n  let released = false;\n  return () => {\n    if (released) return;\n    released = true;\n    releaseCurrent();\n    if (threadTails.get(threadId) === tail) threadTails.delete(threadId);\n  };\n}\n\nfunction releaseWhenDone(stream: ReadableStream<Uint8Array>, release: () => void) {\n  const reader = stream.getReader();\n  return new ReadableStream<Uint8Array>({\n    async pull(controller) {\n      try {\n        const { done, value } = await reader.read();\n        if (done) {\n          release();\n          controller.close();\n          return;\n        }\n        controller.enqueue(value);\n      } catch (error) {\n        release();\n        controller.error(error);\n      }\n    },\n    async cancel(reason) {\n      release();\n      try {\n        await reader.cancel(reason);\n      } catch {\n        // The downstream is already gone; the queue still must be released.\n      }\n    },\n  });\n}\n\nfunction threadIdFromMetadata(raw?: string) {\n  if (!raw) return undefined;\n  try {\n    const value = JSON.parse(raw)?.thread_id;\n    return typeof value === \"string\" && value ? value : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\nBun.serve({\n  hostname: listenHost,\n  port: listenPort,\n  // Browser generation can remain silent while ChatGPT loads or reasons.\n  idleTimeout: 0,\n  async fetch(req) {\n    const incoming = new URL(req.url);\n    if (incoming.pathname === \"/omp-shim-health\") {\n      return Response.json({ service: \"omp-codex-web-shim\", upstreamOrigin, listenPort });\n    }\n    let pathname = incoming.pathname;\n\n    if (pathname === \"/v1/codex/responses\") pathname = \"/v1/responses\";\n    if (pathname === \"/v1/codex/responses/compact\") pathname = \"/v1/responses/compact\";\n\n    const upstreamUrl = new URL(pathname + incoming.search, upstreamOrigin);\n    const headers = new Headers(req.headers);\n    const requestCwd = headers.get(cwdHeader)?.trim();\n    const headerTurnMetadata = headers.get(\"x-codex-turn-metadata\") ?? undefined;\n    let threadId = threadIdFromMetadata(headerTurnMetadata);\n    let turnId: string | undefined;\n    headers.delete(\"host\");\n    headers.delete(cwdHeader);\n\n    let body: BodyInit | undefined;\n    if (req.method !== \"GET\" && req.method !== \"HEAD\") {\n      const bytes = new Uint8Array(await req.arrayBuffer());\n      body = bytes;\n      if (incoming.pathname === \"/v1/codex/responses\"\n        && headers.get(\"content-type\")?.includes(\"application/json\")) {\n        try {\n          const parsed = record(JSON.parse(new TextDecoder().decode(bytes)));\n          const labelResponse = parsed && taskLabelResponse(parsed);\n          if (labelResponse) {\n            console.log(\"OMP local task label\", { model: parsed!.model });\n            return labelResponse;\n          }\n          const sessionCwd = typeof parsed?.__omp_cwd === \"string\" && isAbsolute(parsed.__omp_cwd)\n            ? parsed.__omp_cwd : requestCwd;\n          if (parsed) delete parsed.__omp_cwd;\n          if (parsed) translateToolCallIds(parsed, \"to-web\");\n          const rewrittenTurnMetadata = parsed && sessionCwd\n            ? addCodexEnvironment(parsed, sessionCwd, headerTurnMetadata)\n            : undefined;\n          const environmentAdded = Boolean(rewrittenTurnMetadata);\n          if (parsed && environmentAdded) {\n            body = JSON.stringify(parsed);\n            // Keep the header projection small; the tool registry belongs in the body.\n            const metadata = JSON.parse(rewrittenTurnMetadata!);\n            if (typeof metadata.turn_id === \"string\") turnId = metadata.turn_id;\n            if (typeof metadata.thread_id === \"string\" && metadata.thread_id) threadId = metadata.thread_id;\n            const { tool_namespaces_info: _tools, ...headerMetadata } = metadata;\n            headers.set(\"x-codex-turn-metadata\", JSON.stringify(headerMetadata).replace(\n              /[\\x7f-\\uffff]/g, char => `\\\\u${char.charCodeAt(0).toString(16).padStart(4, \"0\")}`,\n            ));\n            console.log(\"OMP request\", {\n              model: parsed.model, cwd: sessionCwd,\n              thread: String(metadata.thread_id).slice(0, 8),\n              turn: String(metadata.turn_id).slice(0, 8),\n              inputItems: Array.isArray(parsed.input) ? parsed.input.length : 0,\n            });\n            headers.delete(\"content-length\");\n          }\n        } catch {\n          // Forward the original body unchanged; upstream will return the real protocol error.\n        }\n      }\n    }\n\n    const shouldSerialize = Boolean(threadId)\n      && (incoming.pathname === \"/v1/codex/responses\" || incoming.pathname === \"/v1/codex/responses/compact\");\n    const releaseThread = shouldSerialize ? await acquireThread(threadId!) : undefined;\n\n    let upstream: Response;\n    try {\n      upstream = await fetch(upstreamUrl, {\n        method: req.method,\n        headers,\n        body,\n        redirect: \"manual\",\n        signal: req.signal,\n      });\n    } catch (error) {\n      releaseThread?.();\n      throw error;\n    }\n\n    const isOmpStream = incoming.pathname === \"/v1/codex/responses\"\n      && upstream.headers.get(\"content-type\")?.includes(\"text/event-stream\") && upstream.body;\n    const responseHeaders = new Headers(upstream.headers);\n    if (isOmpStream) responseHeaders.delete(\"content-length\");\n    const guardedBody = isOmpStream && threadId && turnId ? guardResponseStream(upstream.body!, {\n      onStall: () => interruptNativeTurn(threadId, turnId),\n      onCancel: () => interruptNativeTurn(threadId, turnId),\n    }) : upstream.body;\n    const responseBody = isOmpStream ? translateResponseStream(guardedBody!) : guardedBody;\n    const serializedBody = releaseThread &&